def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_def = 0
    for me, opp in history:
        if opp == 'D':
            opp_def += 1

    if opp_def == 0:
        return 'C'

    if n >= 15:
        after_my_C = 0
        opp_D_after_my_C = 0
        for i in range(1, n):
            if history[i-1][0] == 'C':
                after_my_C += 1
                if history[i][1] == 'D':
                    opp_D_after_my_C += 1
        if after_my_C >= 5 and opp_D_after_my_C * 4 > after_my_C:
            return 'D'

    last_opp = history[-1][1]
    last_me = history[-1][0]
    opp_def_rate = opp_def / n

    if last_opp == 'D':
        if n >= 2 and history[-2][1] == 'D':
            return 'D'
        if opp_def_rate < 0.2:
            return 'C'
        else:
            return 'D'
    else:
        return 'C'
